SELECT (SELECT minimum FROM public.version ORDER BY id DESC LIMIT 1) AS minimum_gtr_version, account.id AS user_id, COALESCE(EXISTS(SELECT 1 FROM (SELECT eligible_source.* FROM public.record eligible_source WHERE NOT EXISTS(SELECT 1 FROM zc_private.record_validation invalid WHERE invalid.id_record=eligible_source.id AND invalid.status='fail')) record WHERE record.id_user=account.id AND record.date_created>=clock_timestamp()-interval '720 hours'),false) AS recent_record, result.rank,result.time FROM (SELECT 1) seed LEFT JOIN public."user" account ON account.steam_id=$2 LEFT JOIN public.track_tournament_result result ON result.id_user=account.id AND result.id_tournament=$1
